class SessionFwd < BasicObject
  def initialize(target)
    @target = target
    @revoked = false
  end
  def method_missing(name, *args, &blk)
    ::Kernel.raise CapabilityRevoked, name.to_s if @revoked
    @target.__send__(name, *args, &blk)
  end
  def respond_to_missing?(name, priv = false) = !@revoked && @target.respond_to?(name, priv)
  def revoke = @revoked = true
end
